// Dedupe users by email, keep first occurrence, drop password field
const users = $input.all().map(item => item.json);
const seen = new Set();
const clean = [];

for (const u of users) {
  if (!seen.has(u.email)) {
    seen.add(u.email);
    clean.push({ id: u.id, name: u.name, email: u.email, role: u.role });
  }
}

return [{ json: { users: clean } }];

