// Parse classifier output safely (Groq/OpenAI response format)
let parsed;
try {
  const raw = $input.all()[0].json.choices[0].message.content;
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { category: 'customer', reason: 'fallback: parse error' };
}

return [{ json: parsed }];

// Match a user whose role equals the classified category
const category = $('Parse Classification').first().json.category;
const users = $('Clean & Dedupe Users').first().json.users;

const match = users.find(u => u.role === category);

return [{
  json: {
    category,
    matchedUser: match || null,
    routedTo: match ? match.email : null,
    routedName: match ? match.name : 'Unassigned',
    fallback: !match
  }
}];

